#!/usr/bin/env python3
"""Windows-safe minimal Creator-style Claude Map hub upgrade.
Only dashboard files are modified by default. Optional local developer skills
are original, manual-only adapters and never overwrite existing skill folders.
"""
import argparse
import datetime
from pathlib import Path
import re
import shutil
import subprocess
import sys

BACKEND = "\n// BEGIN VIDEO DEVELOPMENT ARCHITECTURE INVENTORY (READ ONLY)\napp.get('/api/development-architecture', (req, res) => {\n  // Return names and booleans only. Do not send raw settings, args, env, headers,\n  // credentials, note contents or absolute paths to the browser.\n  const home = process.env.USERPROFILE || process.env.HOME;\n  if (!home) return res.status(500).json({ error: 'Home directory unavailable' });\n  const root = path.join(home, '.claude');\n  const vault = path.join(home, 'Documents', 'Claude-Dev-Vault');\n  const sensitiveOrNonDev = /(^|[-_: ])(social|youtube|tiktok|instagram|facebook|influencer|marketing|remotion|video|media)([-_: ]|$)/i;\n  const entries = { skills: new Map(), commands: new Map() };\n  const allowed = value => typeof value === 'string' && value.length > 0\n     && value.length <= 120 && !sensitiveOrNonDev.test(value);\n\n  function add(kind, name, source) {\n    if (allowed(name)) entries[kind].set(name, { name, source });\n  }\n  // Bounded, symlink-free walk; reads file names, not file contents.\n  function walk(dir, depth, visit, remaining) {\n    if (depth > 9 || remaining.n <= 0 || !fs.existsSync(dir)) return;\n    let items;\n    try { items = fs.readdirSync(dir, { withFileTypes: true }); }\n    catch { return; }\n    for (const item of items) {\n      if (--remaining.n < 0) break;\n      if (item.isSymbolicLink()) continue;\n      if (item.isDirectory()) {\n        if (/^(node_modules|\\.git|\\.next|dist|build|tmp)$/i.test(item.name)) continue;\n        walk(path.join(dir, item.name), depth + 1, visit, remaining);\n      } else if (item.isFile()) visit(dir, item.name);\n    }\n  }\n  const primarySkills = path.join(root, 'skills');\n  walk(primarySkills, 0, (dir, name) => {\n    if (name.toLowerCase() === 'skill.md') add('skills', path.basename(dir), 'user');\n  }, { n: 4500 });\n  const commandsDir = path.join(root, 'commands');\n  walk(commandsDir, 0, (dir, name) => {\n    if (!name.toLowerCase().endsWith('.md')) return;\n    const base = name.slice(0, -3);\n    const rel = path.relative(commandsDir, dir).split(path.sep).filter(Boolean);\n    add('commands', rel.length ? rel.join(':') + ':' + base : base, 'user');\n  }, { n: 3500 });\n  // Installed plugin skills/commands are in the plugin cache, not ~/.claude/skills.\n  const cache = path.join(root, 'plugins', 'cache');\n  walk(cache, 0, (dir, name) => {\n    const segments = dir.split(path.sep);\n    const skillIndex = segments.lastIndexOf('skills');\n    const cmdIndex = segments.lastIndexOf('commands');\n    const source = segments.find(s => /superpowers|ralph[-_]skills/i.test(s)) || 'plugin';\n    const prefix = /superpowers/i.test(source) ? 'superpowers'\n       : /ralph[-_]skills/i.test(source) ? 'ralph-skills' : '';\n    if (name.toLowerCase() === 'skill.md' && skillIndex !== -1) {\n      const skillName = path.basename(dir);\n      add('skills', skillName, 'plugin');\n      if (prefix) add('skills', prefix + ':' + skillName, 'plugin');\n    }\n    if (name.toLowerCase().endsWith('.md') && cmdIndex !== -1) {\n      const commandName = name.slice(0, -3);\n      if (prefix) add('commands', prefix + ':' + commandName, 'plugin');\n    }\n  }, { n: 6000 });\n\n  function mdNames(dir) {\n    try { return fs.readdirSync(dir).filter(s => s.endsWith('.md'))\n       .map(s => s.slice(0, -3)).filter(allowed).sort(); }\n    catch { return []; }\n  }\n  const settings = (() => { try {\n    return JSON.parse(fs.readFileSync(path.join(root, 'settings.json'), 'utf8'));\n  } catch { return {}; } })();\n  const userConfig = (() => { try {\n    return JSON.parse(fs.readFileSync(path.join(home, '.claude.json'), 'utf8'));\n  } catch { return {}; } })();\n  const hooks = ['skill-gate-check', 'vault-session-init', 'log-to-vault',\n    'stop-vault-log', 'dead-code-check'].map(name => ({\n      name, present: fs.existsSync(path.join(root, 'hooks', name + '.mjs'))\n  }));\n  const config = [\n    ['CLAUDE.md', path.join(root, 'CLAUDE.md')],\n    ['skill-gates.json', path.join(root, 'workflows', 'skill-gates.json')],\n    ['personas', path.join(root, 'personas')],\n    ['commands', path.join(root, 'commands')],\n    ['wave-protocol.md', path.join(root, 'workflows', 'wave-protocol.md')],\n    ['completion-mandate.md', path.join(root, 'workflows', 'completion-mandate.md')],\n    ['developer-orchestration.md', path.join(root, 'rules', 'developer-orchestration.md')]\n  ].map(([name, file]) => ({ name, present: fs.existsSync(file) }));\n  const memory = ['Sessions','Learnings','ADRs','Dispatch-Logs','PRDs','Diagrams',\n    'Projects','Templates'].map(name => ({name,\n      present: fs.existsSync(path.join(vault, name)) }));\n  const mcp = Object.entries(userConfig.mcpServers || {}).filter(([name]) => allowed(name))\n    .map(([name, cfg]) => ({name, transport: cfg?.type === 'http' ? 'http'\n       : cfg?.type === 'sse' ? 'sse' : 'stdio'}));\n  // Built-in labels are only suggestions from the previously observed Claude CLI.\n  // Not file-detected. They never count as locally installed.\n  const builtinCandidates = ['simplify', 'code-review', 'security-review'];\n  const evidence = [];\n  try {\n    const proof = path.join(root, 'state', 'ship-evidence.jsonl');\n    if (fs.existsSync(proof)) {\n      const lines = fs.readFileSync(proof, 'utf8').split(/\\r?\\n/).slice(-100);\n      for (const line of lines) {\n        try {\n          const item = JSON.parse(line.replace(/^\\uFEFF/, ''));\n          if (!['lint','tests','typecheck','build','security','review'].includes(item.check)) continue;\n          if (!Number.isInteger(item.exitCode)) continue;\n          const project = String(item.project || '');\n          if (project.length > 150) continue;\n          evidence.push({check: item.check, exitCode:item.exitCode,\n            project:project, at:String(item.at || '').slice(0,28),\n            // No raw commands, console output or source files disclosed.\n            provenance: 'local manual check recorder'});\n        } catch {}\n      }\n    }\n  } catch {}\n  const enabledPlugins = Object.entries(settings.enabledPlugins || {})\n    .filter(([name, active]) => active === true && allowed(name))\n    .map(([name]) => name);\n  // Some plugin-managed skills are under nested skills directories.\n  // We never mark a name detected without a SKILL.md on disk.\n  const allSkillRoots = [path.join(root, 'plugins', 'marketplaces')];\n  for (const r of allSkillRoots) walk(r, 0, (dir, name) => {\n    if (name.toLowerCase() !== 'skill.md') return;\n    const parts = dir.split(path.sep);\n    if (!parts.includes('skills')) return;\n    const label = path.basename(dir);\n    add('skills', label, 'marketplace');\n  }, { n: 3000 });\n  res.setHeader('Cache-Control', 'no-store');\n  res.json({\n    builtinCandidates, enabledPlugins, evidence,\n    skills: [...entries.skills.values()].sort((a,b) => a.name.localeCompare(b.name)),\n    commands: [...entries.commands.values()].sort((a,b) => a.name.localeCompare(b.name)),\n    agents: mdNames(path.join(root, 'agents')),\n    hooks,\n    events: Object.keys(settings.hooks || {}).filter(allowed),\n    config, memory,\n    obsidianVaultPresent: fs.existsSync(vault),\n    obsidianConfigPresent: fs.existsSync(path.join(vault, '.obsidian')),\n    mcp,\n    // No implementation/agent telemetry is captured. Do not claim tasks ran.\n    runEvidenceAvailable: false\n  });\n});\n\n// Optional explicit check of local CLI MCP connections; never invoked on page load.\napp.get('/api/development-mcp-status', (req, res) => {\n  const cp = require('node:child_process');\n  cp.exec('claude mcp list', {timeout:45000, maxBuffer:1024*1024, windowsHide:true},\n    (error, stdout) => {\n      if (error) return res.status(503).json({error:'Claude CLI status unavailable'});\n      const servers = [];\n      for (const line of String(stdout).split(/\\r?\\n/)) {\n        const idx = line.indexOf(': ');\n        if (idx < 1) continue;\n        const name = line.slice(0, idx).trim();\n        if (!name || name.length > 125 || /social|facebook|youtube|tiktok|instagram|vidiq|marketing/i.test(name)) continue;\n        const tail = line.slice(idx+2);\n        const status = /Connected\\s*$/i.test(tail) ? 'Connected'\n          : /Failed to connect|Connection failed|Disconnected|not connected/i.test(tail) ? 'Unavailable' : 'Unknown';\n        servers.push({name, status});\n      }\n      res.setHeader('Cache-Control', 'no-store');\n      res.json({servers});\n    });\n});\n// END VIDEO DEVELOPMENT ARCHITECTURE INVENTORY\n\n"
FRONTEND = '// BEGIN MINIMAL DEV SYSTEM HUB V2\n// Inventory UI; no agent execution, repositories modification, or web calls.\nconst VIDEO_GROUPS = [\n {title:\'Orchestration\',items:[\'team-driven-development\',\'dispatching-parallel-agents\',\'writing-plans\',\'executing-plans\',\'sc:workflow\']},\n {title:\'Quality\',items:[\'simplify\',\'code-review\',\'clean-code-typescript\',\'karpathy-guidelines\',\'code-splitting\',\'gauge-improvements\',\'security-review\',\'verification-before-completion\']},\n {title:\'Development\',items:[\'test-driven-development\',\'using-git-worktrees\',\'finishing-a-development-branch\',\'receiving-code-review\',\'fix-build\']},\n {title:\'Debugging\',items:[\'systematic-debugging\',\'test-fixing\',\'root-cause-analysis\']},\n {title:\'Discovery\',items:[\'superpowers:brainstorming\',\'sc:brainstorm\',\'ralph-skills:prd\',\'sc:research\']},\n {title:\'Design\',items:[\'frontend-design\',\'ui-ux-pro-max\',\'web-design-guidelines\',\'figma:figma-use\']},\n {title:\'Writing\',items:[\'humanizer\',\'elements-of-style\',\'sc:document\',\'claude-md-management\']},\n {title:\'Integrations\',items:[\'vercel:nextjs\',\'vercel:ai-sdk\',\'vercel:deploy\',\'react-native-best-practices\',\'expo:deployment\',\'stripe:best-practices\',\'sentry:sentry-workflow\',\'atlassian:triage-issue\',\'Notion:search\']},\n {title:\'Operations\',items:[\'sc:pm\',\'ship-learn-next\',\'claude-api\']}\n];\nconst VIDEO_STAGES = [\n {id:\'triage\',name:\'Triage\',desc:\'Understand the request, review context and find reusable solutions.\',tools:[\'superpowers:brainstorming\',\'sc:research\',\'ralph-skills:prd\']},\n {id:\'contract\',name:\'Contract\',desc:\'Define scope, acceptance criteria, plan and file ownership.\',tools:[\'writing-plans\',\'skill-gates.json\',\'sc:workflow\']},\n {id:\'dispatch\',name:\'Dispatch\',desc:\'Split independent work safely; avoid overlapping file ownership.\',tools:[\'dispatching-parallel-agents\',\'executing-plans\',\'wave-protocol.md\']},\n {id:\'review\',name:\'Review\',desc:\'Review source changes, tests, quality and security.\',tools:[\'code-review\',\'security-review\',\'verification-before-completion\']},\n {id:\'ship\',name:\'Ship\',desc:\'Record actual verification, prepare release notes and obtain deployment approval.\',tools:[\'simplify\',\'code-review\',\'reuse-audit\',\'dead-code-scan\',\'vault-learning\']}\n];\nconst VIDEO_MANDATE = [\'simplify\',\'code-review\',\'reuse-audit\',\'dead-code-scan\',\'vault-learning\'];\nconst VIDEO_ROLES = [\n [\'tech lead\',\'system-architect\'],[\'backend\',\'backend-architect\'],[\'frontend\',\'frontend-architect\'],\n [\'design\',\'frontend-architect\'],[\'QA\',\'quality-engineer\'],[\'security\',\'security-engineer\'],\n [\'PM\',\'pm-agent\'],[\'devops\',\'devops-architect\'],[\'writer\',\'technical-writer\'],\n [\'product\',\'requirements-analyst\'],[\'diagrams\',\'\']\n];\n// Known relevant integrations: they are related MCP capabilities, NOT an installed skill.\nconst DEV_RELATED_MCP = {\n \'figma:figma-use\':\'figma\', \'vercel:nextjs\':\'vercel\', \'vercel:ai-sdk\':\'vercel\',\n \'vercel:deploy\':\'vercel\', \'stripe:best-practices\':\'stripe\',\n \'sentry:sentry-workflow\':\'sentry\', \'atlassian:triage-issue\':\'atlassian\',\n \'Notion:search\':\'notion\', \'expo:deployment\':\'expo\'\n};\n// Honest equivalent labels; do not claim these video skill names are installed.\nconst DEV_RELATED_SKILL = {\n \'karpathy-guidelines\':\'pragmatic-code-guidelines\',\n \'elements-of-style\':\'technical-style-guide\'\n};\nfunction renderDevelopmentHub() {\n const inv=window.__videoHubInventory;\n if (!inv) {\n   if (!window.__videoHubLoading) {\n     window.__videoHubLoading=true;\n     fetch(\'/api/development-architecture\',{cache:\'no-store\'})\n       .then(r=>{if(!r.ok)throw new Error(\'Inventory unavailable\');return r.json();})\n       .then(d=>{window.__videoHubInventory=d;window.__videoHubError=null;})\n       .catch(e=>{window.__videoHubError=String(e.message||e);})\n       .finally(()=>{window.__videoHubLoading=false;if(State.currentTab===\'devhub\')renderTabContent();});\n   }\n   return `<div class="mh-shell"><h1>Development System</h1><p>${escapeHtml(window.__videoHubError||\'Loading local inventory...\')}</p></div>`;\n }\n const safe=s=>escapeHtml(String(s??\'\'));\n const raw=[...(inv.skills||[]),...(inv.commands||[])].map(x=>x.name);\n const exact=new Set(raw.map(x=>x.toLowerCase()));\n const bare=new Set(raw.map(x=>x.toLowerCase().split(\':\').pop()));\n const builtin=new Set((inv.builtinCandidates||[]).map(x=>x.toLowerCase()));\n const config=new Set((inv.config||[]).filter(x=>x.present).map(x=>x.name.toLowerCase()));\n const mcps=new Set((inv.mcp||[]).map(x=>x.name.toLowerCase()));\n const status=n=>{\n   const name=n.toLowerCase();\n   if (name.endsWith(\'.json\')||name.endsWith(\'.md\')) return config.has(name) ? [\'file\',\'Present\'] : [\'missing\',\'Missing file\'];\n   if (name.includes(\':\') ? exact.has(name) : (exact.has(name)||bare.has(name))) return [\'installed\',\'Detected\'];\n   if (builtin.has(name)) return [\'builtin\',\'Built-in*\'];\n   if (DEV_RELATED_SKILL[n] && (exact.has(DEV_RELATED_SKILL[n]) || bare.has(DEV_RELATED_SKILL[n]))) return [\'alternative\', \'Via local skill\'];\n   const provider=DEV_RELATED_MCP[n];\n   if (provider && mcps.has(provider.toLowerCase())) return [\'alternative\',\'Via \'+provider+\' MCP\'];\n   return [\'missing\',\'Not found\'];\n };\n const chip=n=>{const [state,desc]=status(n);\n   return `<span class="mh-chip mh-${state}" title="${safe(desc)}">${safe(n)}<span>${safe(desc)}</span></span>`;\n };\n const countAvailable=items=>items.filter(n=>status(n)[0]!==\'missing\').length;\n const active=VIDEO_STAGES.find(x=>x.id===(window.__videoStage||\'triage\'))||VIDEO_STAGES[0];\n window.showVideoStage=id=>{if(VIDEO_STAGES.some(x=>x.id===id)){window.__videoStage=id;if(State.currentTab===\'devhub\')renderTabContent();}};\n const stageHtml=VIDEO_STAGES.map((x,i)=>`<button type="button" class="mh-stage ${x.id===active.id?\'active\':\'\'}" onclick="showVideoStage(\'${x.id}\')"><small>0${i+1}</small><strong>${safe(x.name)}</strong></button>`).join(\'\');\n const groupHtml=VIDEO_GROUPS.map(g=>`<section class="mh-card"><header><strong>${safe(g.title)}</strong><small>${countAvailable(g.items)} / ${g.items.length} available or related</small></header><div class="mh-chips">${g.items.map(chip).join(\'\')}</div></section>`).join(\'\');\n const roles=VIDEO_ROLES.map(([r,a])=>{\n   const found=a && (inv.agents||[]).some(n=>n.toLowerCase()===a.toLowerCase());\n   return `<span class="mh-chip ${found?\'mh-installed\':\'mh-missing\'}" title="${safe(a||\'Unmapped role\')}">${safe(r)}<span>${found?safe(a):\'Unmapped\'}</span></span>`;\n }).join(\'\');\n const layer=(name,detail,html)=>`<section class="mh-layer"><header><h2>${safe(name)}</h2><small>${safe(detail)}</small></header>${html}</section>`;\n const allHooks=(inv.hooks||[]).map(x=>`<span class="mh-chip ${x.present?\'mh-installed\':\'mh-missing\'}">${safe(x.name)}<span>${x.present?\'File found\':\'Missing\'}</span></span>`).join(\'\');\n const allConfig=(inv.config||[]).map(x=>`<span class="mh-chip ${x.present?\'mh-installed\':\'mh-missing\'}">${safe(x.name)}<span>${x.present?\'File found\':\'Missing\'}</span></span>`).join(\'\');\n const vaultChips=[`<span class="mh-chip ${inv.obsidianVaultPresent?\'mh-installed\':\'mh-missing\'}">Obsidian vault<span>${inv.obsidianConfigPresent?\'Opened\':\'Directory only\'}</span></span>`,...(inv.memory||[]).map(x=>`<span class="mh-chip ${x.present?\'mh-installed\':\'mh-missing\'}">${safe(x.name)}<span>${x.present?\'Found\':\'Missing\'}</span></span>`)].join(\'\');\n const allMcps=(inv.mcp||[]).map(x=>`<span class="mh-chip mh-installed">${safe(x.name)}<span>${safe(x.transport)} · configured</span></span>`).join(\'\');\n window.checkDevMcpStatus=()=>{\n   if (window.__hubMcpChecking) return;\n   window.__hubMcpChecking=true;\n   fetch(\'/api/development-mcp-status\',{cache:\'no-store\'})\n    .then(r=>{if(!r.ok)throw new Error(\'CLI status unavailable\');return r.json();})\n    .then(d=>{window.__hubLiveMcp=d.servers||[];window.__hubMcpError=null;})\n    .catch(e=>{window.__hubMcpError=String(e.message||e);})\n    .finally(()=>{window.__hubMcpChecking=false;if(State.currentTab===\'devhub\')renderTabContent();});\n };\n const liveStatus=window.__hubLiveMcp;\n const liveMcpHtml=liveStatus ? `<p class="mh-note">CLI report: ${liveStatus.filter(x=>x.status===\'Connected\').length} connected of ${liveStatus.length} displayed servers</p><div class="mh-chips">${liveStatus.map(x=>`<span class="mh-chip ${x.status===\'Connected\'?\'mh-installed\':\'mh-missing\'}">${safe(x.name)}<span>${safe(x.status)}</span></span>`).join(\'\')}</div>`\n   : `<p class="mh-note">${safe(window.__hubMcpError||\'Click to check plugin and Claude.ai MCP connections.\')}</p>`;\n\n const evidence=(inv.evidence||[]).slice(-15);\n const evidenceHtml=evidence.length ? `<div class="mh-evidence">${evidence.map(x=>`<div><strong>${safe(x.check)}</strong><span>${x.exitCode===0?\'Exit 0\':\'Exit \'+safe(x.exitCode)} · ${safe(x.at)} · ${safe(x.project)}</span></div>`).join(\'\')}</div>` : \'<p class="mh-note">No recorded verification yet. Displaying a checklist never runs tests.</p>\';\n const ship=active.id===\'ship\'?`<div class="mh-ship"><h3>Ship preflight</h3><div class="mh-preflight">${[\'Scope and diff reviewed\',\'Lint and typecheck executed\',\'Tests executed\',\'Relevant build executed\',\'Security and secrets checked\',\'Reuse and dead code checked\',\'PR and changelog prepared\',\'Deployment and rollback approved\',\'Approved vault note saved\'].map(t=>`<div><span aria-hidden="true">○</span> ${safe(t)}</div>`).join(\'\')}</div><h3>Recorded command evidence</h3>${evidenceHtml}</div>`:\'\';\n const reg=(inv.enabledPlugins||[]).map(n=>`<span class="mh-chip mh-installed">${safe(n)}<span>Enabled plugin</span></span>`).join(\'\');\n return `<style>\n .mh-shell,.mh-shell *{box-sizing:border-box}\n .mh-shell{--mh-bg:#111214;--mh-panel:#181a1d;--mh-panel2:#202226;--mh-border:#383b40;--mh-fg:#eeeff0;--mh-muted:#afb0b4;--mh-dim:#888a8e;color:var(--mh-fg);background:transparent;padding:0 0 50px;font-size:13px;line-height:1.5}\n .mh-shell h1{font-size:23px;letter-spacing:-.5px;font-weight:600;color:var(--mh-fg);margin:4px 0 6px}\n .mh-shell h2{font-size:14px;font-weight:600;color:var(--mh-fg);margin:0}\n .mh-shell h3{font-size:12px;color:var(--mh-fg);margin:10px 0 8px}\n .mh-eyebrow{font-size:10px;text-transform:uppercase;letter-spacing:1.7px;color:var(--mh-muted)}\n .mh-sub{font-size:12px;color:var(--mh-muted);margin:0 0 16px}\n .mh-layer{background:var(--mh-panel);border:1px solid var(--mh-border);border-radius:7px;padding:16px;margin-bottom:10px}\n .mh-layer>header{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px;flex-wrap:wrap}\n .mh-layer small,.mh-card small,.mh-note{font-size:11px;color:var(--mh-muted)}\n .mh-stages{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px}\n .mh-stage{border:1px solid var(--mh-border);border-radius:5px;background:var(--mh-bg);padding:13px 5px;color:var(--mh-fg);display:flex;flex-direction:column;align-items:center;gap:2px;cursor:pointer;min-width:0}\n .mh-stage small{font-size:10px;color:var(--mh-muted)} .mh-stage strong{font-size:12px;font-weight:550}\n .mh-stage.active,.mh-stage:hover{background:var(--mh-panel2);border-color:#d1d3d5}.mh-check-button{width:auto;margin:12px 0;display:inline-flex;}\n .mh-stage-info{color:var(--mh-muted);font-size:12px;margin:12px 0 8px}\n .mh-chips{display:flex;flex-wrap:wrap;align-items:center;gap:6px}\n .mh-chip{display:inline-flex;align-items:center;gap:6px;padding:5px 8px;border:1px solid var(--mh-border);border-radius:5px;background:var(--mh-bg);color:var(--mh-fg);font-size:11px;word-break:break-word;max-width:100%}\n .mh-chip span{font-size:10px;color:var(--mh-muted)}\n .mh-installed,.mh-file{border-color:#676a70}.mh-builtin{border-style:dashed;border-color:#9b9da0}.mh-alternative{border-style:dotted;border-color:#777980}\n .mh-missing{opacity:.58;border-style:dashed}\n .mh-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-bottom:10px}\n .mh-card{background:var(--mh-panel);border:1px solid var(--mh-border);border-radius:7px;padding:15px;min-width:0}\n .mh-card header{display:flex;justify-content:space-between;align-items:start;gap:8px;margin-bottom:12px;flex-wrap:wrap}.mh-card strong{font-size:12px;font-weight:600}\n .mh-ship{background:var(--mh-panel2);border:1px solid var(--mh-border);border-radius:6px;padding:13px;margin-top:12px}\n .mh-preflight{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;color:var(--mh-muted);font-size:11px}\n .mh-preflight span{color:var(--mh-dim)}.mh-evidence>div{display:flex;justify-content:space-between;gap:10px;padding:5px 0;border-top:1px solid var(--mh-border);font-size:11px}\n .mh-evidence span{color:var(--mh-muted)}.mh-footer{font-size:11px;color:var(--mh-muted);padding:10px 2px}\n @media(max-width:900px){.mh-grid,.mh-preflight{grid-template-columns:1fr}}@media(max-width:650px){.mh-stages{grid-template-columns:repeat(3,minmax(0,1fr))}}\n </style><div class="mh-shell">\n <div class="mh-eyebrow">Development system / Local inventory</div><h1>Developer Orchestration</h1>\n <p class="mh-sub">Minimal workspace · Installed, built-in and equivalent capabilities identified separately · No model execution</p>\n ${layer(\'Workflow Surface\',\'Five-stage pipeline\',`<div class="mh-stages">${stageHtml}</div><p class="mh-stage-info"><strong>${safe(active.name)}:</strong> ${safe(active.desc)}</p><div class="mh-chips">${active.tools.map(chip).join(\'\')}</div>${ship}`)}\n ${layer(\'Completion Mandate\',\'Capability does not imply executed\',`<div class="mh-chips">${VIDEO_MANDATE.map(chip).join(\'\')}</div>`)}\n ${layer(\'Agent Layer\',`${(inv.agents||[]).length} installed definitions`, `<div class="mh-chips">${roles}</div><p class="mh-note">${(inv.agents||[]).map(safe).join(\' · \')}</p>`)}\n ${layer(\'Skill Layer\',`${(inv.skills||[]).length} discovered entries · ${(inv.commands||[]).length} commands`, `<div class="mh-grid">${groupHtml}</div><p class="mh-note">Detected = matching local skill or command. Built-in* = previously seen in Claude CLI; verify in /skills. Via MCP = related service, not the original skill.</p>`)}\n ${layer(\'Hook Layer\',`${(inv.events||[]).length} event types`, `<div class="mh-chips">${allHooks}</div>`)}\n ${layer(\'Config Layer\',\'Local files only\', `<div class="mh-chips">${allConfig}</div>`)}\n ${layer(\'Memory Layer\',\'Obsidian and approved notes\', `<div class="mh-chips">${vaultChips}</div>`)}\n ${layer(\'MCP Layer\',`${(inv.mcp||[]).length} configured user servers`, `<div class="mh-chips">${allMcps}</div><button type="button" class="mh-stage mh-check-button" onclick="checkDevMcpStatus()">${window.__hubMcpChecking?\'Checking...\':\'Check live MCP connections\'}</button>${liveMcpHtml}`)}\n ${layer(\'Plugin Layer\',`${(inv.enabledPlugins||[]).length} enabled plugins`, `<div class="mh-chips">${reg||\'No plugin configuration entries found.\'}</div>`)}\n <p class="mh-footer">Read-only dashboard. Status is based on local files and known categories; nothing is run by opening this view. No social media functionality.</p>\n </div>`;\n}\n// END MINIMAL DEV SYSTEM HUB V2\n'

