def replace_block(original, start, end, replacement, label):
    if original.count(start) != 1 or original.count(end) != 1:
        raise RuntimeError(f"{label}: installed video dashboard markers not found uniquely; no changes applied")
    i=original.index(start)
    j=original.index(end, i)+len(end)
    return original[:i]+replacement+original[j:]

def run(args):
    root=Path(args.map_dir) if args.map_dir else Path.home()/"AppData"/"Roaming"/"npm"/"node_modules"/"claude-map"
    server=root/"server.js"
    client=root/"public"/"app.js"
    if not server.is_file() or not client.is_file():
        raise RuntimeError(f"Claude Map not found at {root}. Supply --map-dir if installed elsewhere")
    before={server:server.read_text(encoding="utf-8"),client:client.read_text(encoding="utf-8")}
    if "// BEGIN MINIMAL DEV SYSTEM HUB V2" in before[client]:
        raise RuntimeError("Minimal hub V2 appears installed already. Re-running would not be safe")
    changes={
      server:replace_block(before[server],
        "// BEGIN VIDEO DEVELOPMENT ARCHITECTURE INVENTORY",
        "// END VIDEO DEVELOPMENT ARCHITECTURE INVENTORY", BACKEND.strip(), "Backend"),
      client:replace_block(before[client],
        "// BEGIN VIDEO DEVELOPMENT SYSTEM HUB",
        "// END VIDEO DEVELOPMENT SYSTEM HUB", FRONTEND.strip(), "Frontend")
    }
    dest=Path.home()/("claude-map-minimal-backup-"+datetime.datetime.now().strftime("%Y%m%d-%H%M%S"))
    if args.dry_run:
        print("Dry-run only; would back up and modify:")
        for target in changes: print(" -",target)
        print("Original local skill adapters available:", ", ".join(SKILLS))
        return
    dest.mkdir(parents=True,exist_ok=False)
    shutil.copy2(server,dest/"server.js")
    shutil.copy2(client,dest/"app.js")
    try:
        for target,content in changes.items(): target.write_text(content,encoding="utf-8")
        for target in changes:
            result=subprocess.run(["node","--check",str(target)],capture_output=True,text=True)
            if result.returncode: raise RuntimeError(f"Node syntax check failed: {target}\n{result.stderr}")
    except Exception:
        for target,original in before.items(): target.write_text(original,encoding="utf-8")
        raise
    print("Dashboard: minimal neutral theme installed; JS syntax verified")
    print("Rollback files:",dest)
    if args.install_skills:
        base=Path(args.claude_dir) if args.claude_dir else Path.home()/".claude"
        installed=[]
        skipped=[]
        for name,contents in SKILLS.items():
            folder=base/"skills"/name
            file=folder/"SKILL.md"
            if folder.exists() or file.exists():
                skipped.append(name)
                continue
            folder.mkdir(parents=True,exist_ok=False)
            file.write_text(contents,encoding="utf-8")
            installed.append(name)
        print("Original manual-only local skills added:",len(installed))
        print("Added:",', '.join(installed) or '(none)')
        print("Skipped existing folders:",', '.join(skipped) or '(none)')
    print("Restart: claude-map -p 8888 (then Ctrl+Shift+R in browser)")
    print("No Claude configuration, API keys, MCP settings or project source files modified by the dashboard upgrade.")

if __name__=="__main__":
    parser=argparse.ArgumentParser()
    parser.add_argument("--map-dir",help="Global claude-map npm directory")
    parser.add_argument("--claude-dir",help="Where to install manual-only original local developer skills")
    parser.add_argument("--dry-run",action="store_true")
    parser.add_argument("--install-skills",action="store_true",help="Add original manual-only development skills missing from existing skills folders")
    a=parser.parse_args()
    try: run(a)
    except Exception as e:
        print("ERROR:",e,file=sys.stderr)
        sys.exit(1)
